import json
import subprocess
from pathlib import Path

root = Path('/app')
expected = {
    'rules/starter.json',
    'rules/growth.json',
    'rules/scale.json',
    'rules/archive.json',
    'rules/transit.json',
    'rules/burst.json',
    'rules/overrides/altmark-logistik.json',
    'rules/overrides/cordoba-health.json',
    'rules/overrides/norrland-grid.json',
    'rules/overrides/vantage-media.json',
}

def same_typed_value(before, after):
    if type(before) is not type(after):
        return False
    if isinstance(before, dict):
        return before.keys() == after.keys() and all(same_typed_value(before[k], after[k]) for k in before)
    if isinstance(before, list):
        return len(before) == len(after) and all(same_typed_value(a, b) for a, b in zip(before, after))
    return before == after

def keys_sorted(value):
    if isinstance(value, dict):
        return list(value) == sorted(value) and all(keys_sorted(v) for v in value.values())
    if isinstance(value, list):
        return all(keys_sorted(v) for v in value)
    return True

changed = set(subprocess.check_output(
    ['git', '-C', str(root), 'diff', '--name-only'], text=True
).splitlines())
assert changed == expected, f'unexpected changed paths: changed={sorted(changed)}, expected={sorted(expected)}'

for rel in sorted(expected):
    path = root / rel
    raw = path.read_bytes()
    assert raw.endswith(b'\n') and not raw.endswith(b'\n\n'), f'bad trailing newline: {rel}'
    current = json.loads(raw)
    previous = json.loads(subprocess.check_output(
        ['git', '-C', str(root), 'show', f'HEAD:{rel}'], text=True
    ))
    assert same_typed_value(previous, current), f'value or type changed: {rel}'
    assert keys_sorted(current), f'keys not recursively sorted: {rel}'
    canonical = (json.dumps(current, sort_keys=True, indent=2) + '\n').encode()
    assert raw == canonical, f'not canonical serialization: {rel}'

print(f'Validated {len(expected)} documents: exact typed values preserved and canonical serialization confirmed.')
print('Changed paths are exactly the ten work-order documents; no raw/ path changed.')
