import json
from pathlib import Path

root = Path('/app')
expected = {
    'starter': {
        'base_fee': '45.00', 'included_units': 5000,
        'rates': ['0.0180', '0.0150', '0.0120'], 'bounds': [25000, 100000, None],
    },
    'growth': {
        'base_fee': '180.00', 'included_units': 50000,
        'rates': ['0.0110', '0.0080', '0.0055'], 'bounds': [100000, 500000, None],
    },
    'scale': {
        'base_fee': '640.00', 'included_units': 250000,
        'rates': ['0.0050', '0.0034', '0.0025'], 'bounds': [1000000, 5000000, None],
    },
    'archive': {
        'base_fee': '22.00', 'included_units': 0,
        'rates': ['0.0009', '0.0005'], 'bounds': [500000, None],
    },
    'transit': {
        'base_fee': '95.00', 'included_units': 10000,
        'rates': ['0.0070', '0.0045'], 'bounds': [200000, None],
    },
    'burst': {
        'base_fee': '310.00', 'included_units': 0,
        'rates': ['0.0280', '0.0220'], 'bounds': [50000, None],
    },
}

rule_paths = sorted((root / 'rules').glob('*.json')) + sorted((root / 'rules/overrides').glob('*.json'))
assert len(rule_paths) == 10
for path in rule_paths:
    raw = path.read_bytes()
    doc = json.loads(raw)
    assert raw == (json.dumps(doc, sort_keys=True, indent=2) + '\n').encode(), f'not canonical: {path}'

for plan, wanted in expected.items():
    doc = json.loads((root / 'rules' / f'{plan}.json').read_text())
    assert doc['base_fee'] == wanted['base_fee'], f'base changed unexpectedly: {plan}'
    assert doc['included_units'] == wanted['included_units'], f'included units changed: {plan}'
    assert [tier['rate'] for tier in doc['tiers']] == wanted['rates'], f'rates mismatch: {plan}'
    assert [tier['upto'] for tier in doc['tiers']] == wanted['bounds'], f'bounds changed: {plan}'

assert not (root / 'raw/rate-extract-2026-07').exists(), 'disputed extract still retained'
print('Validated all 10 canonical rule documents.')
print('All 6 plan tier schedules match the published notice.')
print('Negotiated base fees, included units, and tier bounds are retained.')
print('The disputed 2026-07 extract drop is retired.')
